// Calculate dynamic icon counts directly from the RARE_ICONS dataset (DB)
const countMap = new Map<string, number>();
for (let i = 0; i < RARE_ICONS.length; i++) {
  const slug = RARE_ICONS[i].categorySlug;
  countMap.set(slug, (countMap.get(slug) || 0) + 1);
}

export const ICON_CATEGORIES: readonly IconCategory[] = RAW_CATEGORIES.map(
  (category) => ({
    name: category.name,
    slug: category.slug,
    iconCount: countMap.get(category.slug) ?? 0,
  }),
);

export const CATEGORY_NAMES = ICON_CATEGORIES.map((category) => category.name);

export function getIconsByCategory(categorySlug: string) {
  return RARE_ICONS.filter((icon) => icon.categorySlug === categorySlug);
}

export function getCategoryBySlug(categorySlug: string) {
  return ICON_CATEGORIES.find((category) => category.slug === categorySlug);
}
